    for(std::uint64_t i=0;i<count;++i) {stop(cancelled);const auto id=r.integer(),revision=r.integer(),kind=r.integer(2);auto label=r.text(256);const auto roi=r.view(32u*1024*1024);charge(roi.second+label.capacity()+sizeof(Annotations::Row));auto geometry=GeometryArchiveCodec::decode(roi.first,roi.second);charge(geometry.payload_bytes());annotations->rows.push_back({id,revision,std::move(label),std::move(geometry),{},ObjectKind(kind)});}
    annotations->bytes=charged;d->annotations=std::move(annotations);prepare_raw_pixel_tiled_snapshot(*d,charged,false);const auto declared_windows=r.integer(tiles.max_windows),declared_scanned=r.integer(o.max_scanned_samples);if(declared_windows!=d->plan.size() || declared_scanned!=d->scanned) throw std::invalid_argument("raw tiled archived candidate coverage mismatch");
    const auto rows=r.integer(o.max_samples),columns=r.integer(128);if(rows<4 || columns!=recipe.feature_schema().size() || rows>r.left/(32+4*columns)) throw std::invalid_argument("raw tiled row payload is truncated/inconsistent");const auto arrays=std::size_t(rows)*(32+4*std::size_t(columns));const auto model_bytes=out->model_?2*out->model_->bytes().size():0;if(d->snapshot+arrays+model_bytes>o.work_bytes || size+d->snapshot+arrays+model_bytes+64*rows>256u*1024*1024) throw std::length_error("raw tiled historical arrays exceed work/retained limit");
